"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0836-01-01:0":{"b": ["Muhammed morreu; Ali b. Muhammed I, de nove anos, subiu ao trono (221, 836).", "0554831c"], "d": ["Muhammed morreu; Ali b. Muhammed I, de nove anos, subiu ao trono (221, 836).", "0554831c"]},
