"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0863-02-24:0":{"b": ["Yahyâ I morreu; com o reinado de Yahyâ II começou a instabilidade (249, 863).", "5aee6f7d"], "d": ["Yahyâ I morreu; com o reinado de Yahyâ II começou a instabilidade (249, 863).", "5aee6f7d"]},
